};

/* list_90_floats_RAM (0x50A800), which game_engine_setup's sub_2E2B0
 * copies from ROM: per attack strength (0x50FE02), the hit's push (its +8
 * scales every knockback) and the rest. Left 0, no hit pushed anyone. */
static const u32 stf_list_90[90] = {
    0x3F800000u, 0x40A00000u, 0x3F800000u, 0x3F800000u, 0x3F800000u, 0x40000000u,
    0x3F800000u, 0x3FC00000u, 0x60004000u, 0x28002400u, 0x40000000u, 0x40900000u,
    0x3F800000u, 0x3F800000u, 0x3F800000u, 0x40000000u, 0x3F800000u, 0x3FC00000u,
    0x60004000u, 0x28002400u, 0x3F800000u, 0x40E00000u, 0x3F800000u, 0x3F800000u,
    0x3F800000u, 0x40000000u, 0x3F800000u, 0x3FC00000u, 0x48004000u, 0x38001000u,
    0x40800000u, 0x41200000u, 0x3F800000u, 0x3F000000u, 0x3F4CCCCDu, 0x3F4CCCCDu,
    0x3ECCCCCDu, 0x3F4CCCCDu, 0x48004000u, 0x38005000u, 0x41A00000u, 0x40C00000u,
    0x3F800000u, 0x3F99999Au, 0x3F800000u, 0x3F99999Au, 0x3F000000u, 0x3F800000u,
    0x60004000u, 0x40002400u, 0x3F800000u, 0x3FC00000u, 0x3F000000u, 0x3F000000u,
    0x3F800000u, 0x40000000u, 0x3F800000u, 0x3FC00000u, 0x60004000u, 0x38002400u,
    0x3F800000u, 0x41000000u, 0x3F800000u, 0x3F800000u, 0x3F800000u, 0x40000000u,
    0x3F800000u, 0x3FC00000u, 0x60004000u, 0x38002400u, 0x3F800000u, 0xC1200000u,
    0x3F800000u, 0x3F800000u, 0x3F800000u, 0x40000000u, 0x3F800000u, 0x3FC00000u,
    0x60004000u, 0x38002400u, 0x3F4CCCCDu, 0x41400000u, 0x3F800000u, 0x3F000000u,
    0x3F000000u, 0x3F000000u, 0x3F000000u, 0x3F000000u, 0x48004000u, 0x48004000u,
};

/* StF's globals as they are in a 2-player fight (a real board's RAM at a
 * fight's start): the modes, the task blocks, the debug flags. */
void stf_globals(void) {
    u32 i;
    for (i = 0; i < sizeof stf_fight_ram / sizeof stf_fight_ram[0]; i += 2)
        RAM32(stf_fight_ram[i]) = stf_fight_ram[i + 1];
    for (i = 0; i < 90u; i++) RAM32(0x50A800u + i * 4u) = stf_list_90[i];
    RAM32(G_GAME_TIMER) = 0x09090000u;     /* game_timer 0, mode 9, also_mode 9 */
    RAM32(G_MODE_FLAG) = 0x200u;
    RAM32(G_SUB_MODE) = 0x0909u;           /* _sub_mode, also_sub_mode */
    RAM32(G_SUB_MODE + 4u) = 0x200u;
    RAM32(G_FA_ROB0) = (u32)robs[0];
    RAM32(G_FA_ROB1) = (u32)robs[1];
    RAM32(G_BACKUP_RAM_PTR) = (u32)stf_ram(G_BACKUP_RAM);
    RAM32(G_FA_COLI) = (u32)stf_coli;
    RAM32(G_FA_GAME_DISP) = (u32)stf_disp;
    RAM32(G_FA_ENEMY0) = (u32)stf_enemy[0];
    RAM32(G_FA_ENEMY1) = (u32)stf_enemy[1];
    RAM32(G_FA_EFFECT) = (u32)stf_effect;
    RAM32(G_FA_OSAGE0) = (u32)stf_osage[0];
    RAM32(G_FA_OSAGE1) = (u32)stf_osage[1];
    RAM32(G_POLYGON_LIMIT) = 5000u;        /* as change_scene sets it */
    RAM32(G_FA_TOBI) = (u32)stf_tobi;
    RAM32(G_FA_CAMERA) = (u32)stf_cam;
    RAM32(G_FA_RECORD) = (u32)stf_rec;
    RAM32(G_FA_OBJ0) = (u32)stf_obj0;
    RAM32(G_DEBUG_FLAG) = 0x18A00u;
}

/* A fighter's rob, as StF sets one up for a round: player p, at (x, 0, 0)
 * with its yaw, playing the stance from its first frame. */
/* Each fighter's collision-ball tables (+0x1D00..0x1D20), as a game mode's
 * start sets them (ADV_CPU_BATTLE_INT): radii, scales, the ball positions
 * and the part each ball rides; cop_initialize_end2 fills them. */
static const u32 rob_balls[2][9] = {
    { 0x50A208u, 0x50A284u, 0x50A288u, 0x506000u, 0x506400u, 0x506480u, 0x506580u, 0x506680u, 0x5066C0u },
    { 0x50A290u, 0x50A30Cu, 0x50A310u, 0x506200u, 0x506440u, 0x506500u, 0x506600u, 0x5066A0u, 0x5066D0u },
};

void rob_init(u32 p, const fighter_t *f) {
    u32 *r = robs[p];
    union { float f; u32 u; } x, z;
    u32 i;
    for (i = 0; i < ROB_SIZE / 4; i++) r[i] = 0u;
    for (i = 0; i < MOT_SIZE / 4; i++) mots[p][i] = 0u;
    x.f = f->x;
    z.f = f->z;
    RW(r, ROB_FLAG) = p ? 0x84000082u : 0x84000080u;
    RB(r, ROB_IDNM) = (u8)p;
    RW(r, TASK_SIZE) = ROB_SIZE;
    RW(r, TASK_FN) = (u32)stf_action_init;
    RW(r, ROB_CONTROL) = 1u << 3;        /* control_init: the pad drives it */
    RW(r, ROB_XPOS) = x.u;
    RW(r, ROB_ZPOS) = z.u;
    RH(r, ROB_YANG) = f->yaw;
    /* player 2 is character + 26 (his other colours, and his own motion
     * list) only against himself, as ROUND_INIT has it */
    RB(r, ROB_CHAR) = (u8)(f->anim->chr + (p && f->anim->chr == RB(robs[0], ROB_CHAR_IS) ? 26u : 0u));
    RB(r, ROB_CHAR_IS) = (u8)f->anim->chr;
    RW(r, ROB_CHAR_REC) = (u32)stf_char(RB(r, ROB_CHAR));
    RW(r, ROB_CHAR_MOTS) = stf_char(RB(r, ROB_CHAR))[3];
    for (i = 0; i < 9u; i++) RW(r, ROB_BALLS + 4u * i) = (u32)stf_ram(rob_balls[p][i]);
    RB(r, ROB_SKELTON_TYPE) = 0xFFu;
    RW(r, ROB_MOT_REC) = (u32)mots[p];
    RW(r, ROB_Y_SCALE) = 0x3F800000u;
    /* The dent pendulums, as the round's start sets them (sub_89BF8 with
     * zero angles): unit scale, then the countdown camera_init runs down
     * each frame; dented_cnt only swings them while it is not negative. */
    for (i = 0; i < 3u; i++) {
        RW(r, ROB_DENT_SCALE + 4u * i) = 0x3F800000u;
        RW(r, ROB_DENT_SCALE2 + 4u * i) = 0x3F800000u;
    }
    RW(r, ROB_DENTED_CNT) = 0u;
}

/* A fighter's first frame: both fighters' collision balls to the
 * coprocessor (cop_initialize_end2, which also clears their active bits),
 * both bodies' pendulums (sub_7F0E8), then the fighter's task from
 * action_init, which sets up its moves and plays the stance. Its sway
 * chains start over, as a round's start starts them: the task is
 * osage_init again. */
void rob_start(u32 p) {
    u32 w0[2] = { RW(robs[0], ROB_FLAG), RW(robs[1], ROB_FLAG) };
    stf_call(stf_cop_initialize_end2, robs[0], robs[1], 0u);
    kage_balls();
    RW(robs[0], ROB_FLAG) = w0[0]; RW(robs[1], ROB_FLAG) = w0[1];
    stf_call(stf_sub_7F0E8, robs[0], robs[1], 0u);
    stf_task((void (*)(void))RW(robs[p], TASK_FN), robs[p], robs[p], robs[p ^ 1u]);
    task_reset(stf_osage[p], sizeof stf_osage[p]);
    RB(stf_osage[p], TASK_IDNM) = (u8)p;
    RW(stf_osage[p], TASK_FN) = (u32)stf_osage_init;
}

/* One 60 Hz frame of StF's fight, its tasks in StF's own order (its task
 * list, read off a real fight): the collision task first (hits and walls,
 * on the poses of the frame before), get_game_info (each fighter's angle
 * and distance to the other, which it turns by), the camera, ROUND_DSP's
 * clock, the effects, rob_control (each player's pad to the fighter's
 * +0x1200, then sub_1D47C, which reads the moves the pad makes), the
 * recorder, then each fighter's task (rob_action: the commands, the action,
 * where a hit's damage is dealt, the motion, the part matrices). The clock
 * runs only while clock_on and, as FIGHT_DSP's, not once a fighter is
 * knocked out (w0 bit 5). The pad is
 * StF's: punch 1, kick 2, guard 4, down 0x10, up 0x20, right 0x40, left
 * 0x80. */
void fight_step(const u32 pad[2], u32 clock_on) {
    u32 p;
    stf_task((void (*)(void))RW(stf_coli, TASK_FN), stf_coli, robs[0], robs[1]);
    stf_task(stf_get_game_info, stf_enemy[0], robs[0], robs[1]);
    stf_task(stf_cam_mode_10, stf_cam, robs[0], robs[1]);
    /* the camera's frame count, which StF's camera_init (os display) moves
     * on each frame: a throw's camera script (sub_6BA98) steps to its next
     * key when the count reaches the key's frame; left still, every key ran
     * past its end and the camera flew off */
    RH(stf_cam, CAMERA_CNT)++;
    if (clock_on && !((RW(robs[0], ROB_FLAG) | RW(robs[1], ROB_FLAG)) & ROB_F_LOST) && GAME_TIMER > 0)
        GAME_TIMER--;
    stf_task((void (*)(void))RW(stf_effect, TASK_FN), stf_effect, robs[0], robs[1]);
    RAM8(G_SOUNDS) = 0u;                 /* GAME_DSP's: the sounds the recorder keeps, from none */
    RAM32(G_SW_HELD) = pad[0] << 8 | pad[1] << 16;
    for (p = 0; p < 2u; p++) RW(robs[p], ROB_DENTED_CNT)--;  /* camera_init's sub_7F5CC */
    for (p = 0; p < 2u; p++) {
        RB(robs[p], ROB_PAD) = (u8)pad[p];
        /* g13 the rob too: the command interpreter keeps its base there */
        stf_task(stf_sub_1D47C, robs[p], robs[p], robs[p ^ 1u]);
    }
    /* the replay's recorder (fa_record): both fighters' frame in the ring */
    stf_task(stf_rec_disp, stf_rec, robs[0], robs[1]);
    for (p = 0; p < 2u; p++)
        stf_task((void (*)(void))RW(robs[p], TASK_FN), robs[p], robs[p], robs[p ^ 1u]);
    /* the projectile task (fa_tobi's sub_89FB8): sub_8A29C steps each live
     * object (Eggman's bombs: fly, burst, the hit test whose hit the next
     * frame's collision task deals); sub_8A2E4 is left out (it tells StF's
     * CPU players where a bomb will burst, and the board has none); then
     * the afterimages */
    stf_task(stf_sub_8A29C, stf_tobi, robs[0], robs[1]);
    stf_call(stf_zanzou_control, robs[0], robs[1], 0u);
    /* GAME_DSP's trail: each fighter's place on the ground, kept for the
     * last 8 frames, where kira_kira_disp puts hyper mode's sparkles */
    for (p = 0; p < 2u; p++) {
        u32 at = RW(robs[p], ROB_TRAIL_AT), k;
        RW(robs[p], ROB_TRAIL_AT) = (at + 1u) & 7u;
        for (k = 0; k < 3u; k++) RW(robs[p], ROB_TRAIL + at * 12u + k * 4u) = RW(robs[p], ROB_GXPOS + k * 4u);
    }
}

/* A round: both fighters back to their marks, the collision task, the
 * clock at StF's 30 seconds (MES_READY_INT: time << 6; the collision task
 * only deals damage while it runs). */
u32 round_time = 30u;             /* seconds, the setup menu's time */


#define COP_ZANZOU_INIT COP_CMD(0x81)

/* Where the fighters start, as StF's ROUND_INIT and SET_INT place them: 4.0
 * apart through the middle along the angle at 0x500432, 0x2000 for a match's
 * first round and a quarter turn more for each round after it, each facing
 * the other. cos(k * 45 degrees) * 2, by k; 1.4142143 is the COP's sqrt 2.
 * On the other games' stages, as those games start a round (read off VF2
 * and FV fights): 2.0 of theirs apart along x, VF2 every round, FV a
 * quarter turn more for each round after the first. Those stages and their
 * fighters are drawn at the guests' size (tools/guests/vf2-guest.mjs SCALE,
 * tools/stages/fv-stages.mjs FV_SCALE), so 2.0 of theirs is 2.0 times that here:
 * about StF's 4.0 (VF2_SCALE: poses.h). */
#define FV_SCALE  (2.676f / 1.309f)
static u16 start_ang;
static const u32 start_cos[8] = {
    0x40000000u, 0x3FB504F7u, 0x00000000u, 0xBFB504F7u, 0xC0000000u, 0xBFB504F7u, 0x00000000u, 0x3FB504F7u,
};
static float start_f(u32 k) { union { u32 u; float f; } v; v.u = start_cos[k & 7u]; return v.f; }

/* half the start distance on stage n: 2, 3, 5 VF2's, 4 FV's, 6 DOA's */
static float start_half(u32 n) {
    if (n == 4u) return 0.5f * FV_SCALE;
    if (n == 2u || n == 3u || n == 5u) return 0.5f * VF2_SCALE;
    return n >= 2u ? 0.5f : 1.0f;
}

/* What the motion setups' ops 5, 9 and 0xA leave in a rob (+0x818..0x83F,
 * the jump's frames +0x5BC..0x5BF and its fall +0x5CC): StF's round start
 * keeps them, and a jump whose setup has no op 9 of its own (Bean's ta_kick
 * out of a roll) steps by the last one's (ACT_RC_JUMP). */
static const u16 setup_keep[][2] = { { 0x818u, 0x840u }, { 0x5BCu, 0x5C0u }, { 0x5CCu, 0x5D0u } };

/* next: the match's next round, the armour as the last one left it */
void round_start(fighter_t fs[2], u32 next) {
    u32 i, k, j, a, w, kept[2][(0x840u - 0x818u + 8u) / 4u];
    u32 n = stage_index();               /* 2, 3 VF2's; 4 FV's */
    float d = start_half(n);
    start_ang = !next ? (n >= 2u ? 0u : 0x2000u) : (u16)(start_ang + (n == 2u || n == 3u ? 0u : 0x4000u));
    k = start_ang >> 13;
    stage_round_start();
    for (i = 0; i < 2u; i++) {
        if (next) armour_keep(i);
        /* at yaw a a fighter faces (-sin a, cos a) in x, z, as StF's
         * camera does */
        fs[i].x = (i ? start_f(k) : -start_f(k)) * d;
        fs[i].z = (i ? start_f(k + 6u) : -start_f(k + 6u)) * d;
        fs[i].yaw = (u16)(start_ang + (i ? 0x4000u : 0xC000u));
        for (j = 0, w = 0; j < 3u; j++)
            for (a = setup_keep[j][0]; a < setup_keep[j][1]; a += 4u) kept[i][w++] = RW(robs[i], a);
        rob_init(i, &fs[i]);
        if (next)
            for (j = 0, w = 0; j < 3u; j++)
                for (a = setup_keep[j][0]; a < setup_keep[j][1]; a += 4u) RW(robs[i], a) = kept[i][w++];
    }
    task_reset(stf_coli, sizeof stf_coli);
    stf_task(stf_coli_init, stf_coli, robs[0], robs[1]);
    /* the projectile task, as fa_tobi starts it: the afterimage ring reset
     * (Fn_zanzou_init) and its 30 objects (0x100 bytes each from +0x200)
     * cleared, so no bomb lives on into the next round */
    *(volatile u32 *)M2_COPFIFO_ADDR = COP_ZANZOU_INIT;
    task_reset(stf_tobi, sizeof stf_tobi);
    for (i = 0; i < 2u; i++) {
        rob_start(i);
        armour_limits(i);
        if (next) armour_back(i);
    }
    /* the effect task, as fa_effect starts it (efc_ram_init: no sparks,
     * smoke or barrier pieces left from the last round), then efc_cont */
    task_reset(stf_effect, sizeof stf_effect);
    stf_task(stf_fa_effect, stf_effect, robs[0], robs[1]);
    /* the scattered rings: none (ring_tobitiri_init, as the battle's start runs it) */
    stf_call(stf_ring_tobitiri_init, robs[0], robs[1], 0u);
    /* the spin attack's models, pulse and drop for both (sub_81038, as
     * StF's battle modes run it before a round) */
    stf_call(stf_sub_81038, robs[0], robs[1], 0u);
    stf_task(stf_cam_mode_9, stf_cam, robs[0], robs[1]);
    GAME_TIMER = (short)(round_time << 6);
    /* stage_x (0x50A00C), the half side of the square area_coli walls the
     * fighters in: StF's cage at 8.0; VF2's ring has no walls, so out of
     * reach (100.0), and the ring out (ring_out_step) at the ring's edge;
     * FV's cage at its own size (FV's 6.0, scaled) */
    RAM32(G_STAGE_X) = cur_stage && m2_obj_fb(cur_stage->ring) ? 0x42C80000u :
                       cur_stage && m2_obj_fb(cur_stage->wall) ? m2_obj_fb(cur_stage->wall) : 0x41000000u;
    ring_out_reset();
    /* no replay, the recorder from the ring's start */
    rep_round();
    RW(stf_rec, REC_NEXT) = 0u;
    /* back to the fight from the last round's judging (ko_disp's K.O. off;
     * its size and turn, stf_disp +0x94 and +0x98, cleared below) */
    RAM8(G_SUB_MODE + 1u) = SUB_FIGHT_DSP;
    RAM8(G_JUDGE) = 0u;
    /* the HUD, as MES_ROUND_INT and MES_READY_INT leave it: both bars
     * from empty, the lamps (clear_win_lamp_cntr's, then win_lamp_int);
     * and MES_FIGHT_INT's barrier boxes (barrier_left_disp_init: each
     * side's box, BARRIER and a chevron a barrier left, or NO BARRIER) */
    for (i = 0; i < sizeof stf_disp / 4; i++) stf_disp[i] = 0u;
    RW(stf_disp, TASK_FLAG) = 0x84800000u;
    for (i = 0; i < 10u; i++) {
        RB(stf_disp, DISP_LAMP0 + i) = i < 5u ? 0x3Fu : 4u;
        RB(stf_disp, DISP_LAMP1 + i) = i < 5u ? 0x3Fu : 4u;
    }
    stf_call(stf_win_lamp_int, robs[0], robs[1], 0u);
    stf_task(stf_barrier_left_disp_init, stf_disp, robs[0], robs[1]);
    armour_hud_load();
}

/* StF's HUD, game_display_cont's part of it: the energy bars, the
 * barriers left, the clock and the round lamps, in StF's own tiles; then
 * the armour, in FV's. */
void hud_draw(void) {
    stf_task(stf_energy_disp, stf_disp, robs[0], robs[1]);
    stf_task(stf_energy_disp, stf_disp, robs[1], robs[0]);
    stf_task(stf_barrier_left_disp, stf_disp, robs[0], robs[1]);
    stf_task(stf_time_dsp, stf_disp, robs[0], robs[1]);
    stf_task(stf_win_lamp_dsp, stf_disp, robs[0], robs[1]);
    armour_hud();
}

/* The fight's state as the boot leaves it: StF's RAM (lift-stf.py lays its
 * blocks out in one run, stf_ram_500000 to the end of stf_ram_599000) and
 * the task blocks its code keeps. Two boards that link both start again from
 * it, whatever each ran before: StF's code keeps state from past fights where
 * a round's start leaves it (the recorder, the CPU players' info, the
 * camera's, the hit sparks' positions). */
static u32 boot_ram[0x18000u / 4];
static u32 boot_blocks[(sizeof robs + sizeof mots + sizeof stf_cam + sizeof stf_rec + sizeof stf_obj0 +
                        sizeof stf_play + sizeof stf_coli + sizeof stf_effect + sizeof stf_tobi +
                        sizeof stf_enemy + sizeof stf_disp + sizeof stf_osage) / 4];

void boot_state(u32 save) {
    u32 *const blk[] = { robs[0], mots[0], stf_cam, stf_rec, stf_obj0, stf_play, stf_coli,
                         stf_effect, stf_tobi, stf_enemy[0], stf_disp, stf_osage[0], (u32 *)stf_ram_500000 };
    const u32 len[] = { sizeof robs, sizeof mots, sizeof stf_cam, sizeof stf_rec, sizeof stf_obj0,
                        sizeof stf_play, sizeof stf_coli, sizeof stf_effect, sizeof stf_tobi,
                        sizeof stf_enemy, sizeof stf_disp, sizeof stf_osage,
                        (u32)(stf_ram_599000 + sizeof stf_ram_599000 - stf_ram_500000) };
    u32 b, i, *k = boot_blocks;
    for (b = 0; b < sizeof len / sizeof len[0]; b++) {
        if (b == sizeof len / sizeof len[0] - 1u) {
            k = boot_ram;
            while (len[b] > sizeof boot_ram) ;   /* StF's RAM outgrew boot_ram: make it bigger */
        }
        for (i = 0; i < len[b] / 4u; i++, k++) {
            if (save) *k = blk[b][i];
            else blk[b][i] = *k;
        }
    }
}

board/src/fight/osage.c:
/*
 * osage.c — the sway chains (Honey's ponytail, Fang's tail): StF's osage
 * tasks, a frame of them, and the list blocks they draw into (osage_splice,
 * clear_buffer_ptr), which the effects use too.
 */
#include "megamix.h"

/* Each fighter's sway chains, a frame of them: its osage task (osage_init
 * the first time, then osage_dsp), after the fighters' part matrices.
 * set_obj_fifo puts each segment straight in the list (a matrix, then the
 * object from the model table) and counts its polygons in POLYGON against
 * POLYGON_LIMIT, which main_loop starts at 0 every frame; the board's own
 * models go through the coprocessor and keep their own count. In a fight
 * osage_dsp draws on the coprocessor's matrix as it finds it, the fighters'
 * unscaled camera (cam_l: set_obj_fifo skips a segment whose m00 is past
 * 1); only the select screen loads 0x501128. */
void osage_step(void) {
    u32 p;
    cop_load(&cam_l);
    RAM32(G_OBJ_COUNT) = 0u;
    RAM32(G_POLYGON) = 0u;
    for (p = 0; p < 2u; p++)
        stf_task((void (*)(void))RW(stf_osage[p], TASK_FN), stf_osage[p], robs[p], robs[p ^ 1u]);
}

/* StF's list blocks: a draw that belongs at another place in the list
 * (osage_dsp's, at the fighter's head) writes a word, its draws and a jump,
 * then turns the word into a jump past them. The layer table (0x501804 +
 * 8 n) holds each layer's first block and the jump at its last one; a block
 * that finds one before it links that jump to itself, and the place it
 * belongs (osage_splice) jumps to the first and has the last jump back.
 * clear_buffer_ptr clears the table every frame. */
void clear_buffer_ptr(void) {
    u32 *e = (u32 *)stf_ram(G_LIST_BLOCKS), i;
    for (i = 0; i < 43u; i++) e[i] = 0u;
}

/* rob_disp's head entry (unit_efc_kao): layer n's blocks run here (player
 * n's osage blocks; layer 6 both players' mirrored ones, which osage_dsp
 * lays on Aurora Icefield). A word, after which the last block's jump comes
 * back (or, with no block yet, the first one's place); the word becomes the
 * jump to the first. */
void osage_splice(u32 n) {
    volatile u32 *geo = (volatile u32 *)GEO_START, *wpos = (volatile u32 *)COP_WPOS_REG;
    u32 *e = (u32 *)stf_ram(G_LIST_BLOCKS + 4u + n * 8u), at = *wpos;
    *geo = 0u;
    if (e[1] == 0u) e[0] = *wpos;
    else *(volatile u32 *)(GEO_BUFFERRAM + e[1]) = *wpos | 0x80000000u;
    *(volatile u32 *)GEO_WRITE_REG = at;
    e[1] = *wpos;
    *geo = e[0] | 0x80000000u;
}

/* The camera osage_dsp draws the chains on, as camera_init stores it for
 * each player (0x501128, 0x501158): read back after its 1.6 scale, cam. */
void osage_camera(void) {
    u32 *c0 = (u32 *)stf_ram(G_ROB_CAMERA0), *c1 = (u32 *)stf_ram(G_ROB_CAMERA1), i;
    for (i = 0; i < 9; i++) c0[i] = c1[i] = m2_obj_fb(cam.r[i]);
    for (i = 0; i < 3; i++) c0[9 + i] = c1[9 + i] = m2_obj_fb(cam.t[i]);
}

board/src/fight/push.c:
/* push.c: the push between two VF2 guests, as VF2's TGP works it out (its
 * function 0x3B, TGP 0x99E; docs/GRADING.md). StF's SHARC program pairs the
 * balls its own way, and on a jab's contact it gives another overlap.
 *
 * The TGP holds 30 balls a fighter. Its ball k has the radius of the rob's
 * ball k (rob+0xD00: x, y, z, r) but the place of ball SENT[k], the order
 * VF2's set_coli_ball_data sends them in. Each pair (1P's ball i, 2P's ball
 * o) not in an attack (bit i of 1P's attack mask, bit o of 2P's) pushes by
 * r_i + r_o - |p_i - p_o|, the largest of them; a pair in both of the
 * kind's masks (VF2's +0xB4 bit i, +0xB8 bit o) is multiplied by the TGP's
 * program word 0xE, which is 0. Kinds 4 and 5 (+0x88) give none. Its
 * other answer (VF2's task +0x148, StF's +0x164) is how many such pairs
 * meet, those multiplied by 0 too: coli_recalc_pos pushes the two apart
 * when it is over 0, by g4 or by how far they are inside each other's
 * reach (VF2 0x236AC). vf2_push leaves it in vf2_push_pairs.
 *
 * The attack mask is VF2's calc_attack_flag's, not StF's (+0x768): VF2 maps
 * ball to unit with its own bytes (UNIT, VF2's 0x23284), where the guest's
 * +0x1D18 holds another order. The part's units are StF's dword_CE020, the
 * same table as VF2's. The kind's masks are VF2's decide_coli_kind's: only
 * BODY, kind 3, has any (0xFFFFDFFC both); StF's +0xC0/+0xC4 are its own.
 * Built for the i960's floating point, as carry.c is: the float goes back
 * as its bits. */
typedef unsigned u32;
typedef unsigned char u8;

#define BALLS 30
static const u8 SENT[BALLS] = { 1, 0, 2, 5, 4, 7, 6, 8, 10, 9, 12, 11, 13, 3, 16,
                                15, 14, 19, 18, 17, 21, 20, 24, 23, 22, 27, 26, 25, 29, 28 };
static const u8 UNIT[BALLS] = { 1, 1, 2, 3, 3, 4, 4, 5, 6, 6, 7, 7, 8, 9, 10,
                                10, 10, 11, 11, 11, 12, 12, 13, 13, 13, 14, 14, 14, 15, 15 };
#define PART_UNITS ((const u32 *)0xCE020)   /* StF's dword_CE020 */
#define NO_PART 41u

/* VF2's calc_attack_flag: the balls on the units of the part attacking. */
static u32 attack_mask(const u8 *rob) {
    u32 part = rob[0x820], units, mask = 0u, k;
    if (!(*(const u32 *)(rob + 0x1A4) >> 8 & 1u)) return 0u;
    if ((u32)*(const short *)(rob + 0x1AA) < (u32)*(const short *)(rob + 0x808)) return 0u;
    if (part == NO_PART) return 0u;
    units = PART_UNITS[part];
    for (k = 0; k < BALLS; k++)
        if (units >> UNIT[k] & 1u) mask |= 1u << k;
    return mask;
}

static float sqrt_r(float v) {
    float r;
    __asm__("sqrtr %1, %0" : "=r"(r) : "r"(v));
    return r;
}

/* The box around a fighter's balls not in its mask (each ball's place ± its
 * radius), lo and hi. */
static void bounds(const float (*b)[4], u32 mask, float *lo, float *hi) {
    u32 k, a;
    for (a = 0; a < 3; a++) lo[a] = 1e30f, hi[a] = -1e30f;
    for (k = 0; k < BALLS; k++) {
        const float *p = b[SENT[k]];
        if (mask >> k & 1u) continue;
        for (a = 0; a < 3; a++) {
            if (p[a] - b[k][3] < lo[a]) lo[a] = p[a] - b[k][3];
            if (p[a] + b[k][3] > hi[a]) hi[a] = p[a] + b[k][3];
        }
    }
}

/* The balls not in the mask whose box meets the other fighter's: only they
 * can overlap one of its balls. */
static u32 near(const float (*b)[4], u32 mask, const float *lo, const float *hi) {
    u32 k, a, out = 0u;
    for (k = 0; k < BALLS; k++) {
        const float *p = b[SENT[k]];
        if (mask >> k & 1u) continue;
        for (a = 0; a < 3; a++)
            if (p[a] - b[k][3] >= hi[a] || p[a] + b[k][3] <= lo[a]) break;
        if (a == 3) out |= 1u << k;
    }
    return out;
}

u32 vf2_push_pairs;

/* The board does it on the i960, not a DSP: the 900 pairs every frame cost
 * it frames, so only the balls near the other fighter are paired (the same
 * result). */
u32 vf2_push(const u8 *rob0, const u8 *rob1, const u8 *task) {
    const float (*b0)[4] = (const float (*)[4])(rob0 + 0xD00);
    const float (*b1)[4] = (const float (*)[4])(rob1 + 0xD00);
    u32 kind = *(const u32 *)(task + 0x88);
    u32 z = kind == 3u ? 0xFFFFDFFCu : 0u, n0, n1, i, o, pairs = 0u;
    float lo0[3], hi0[3], lo1[3], hi1[3], best = 0.0f;
    union { float f; u32 u; } out;
    n0 = attack_mask(rob0), n1 = attack_mask(rob1);
    bounds(b0, n0, lo0, hi0), bounds(b1, n1, lo1, hi1);
    n0 = near(b0, n0, lo1, hi1), n1 = near(b1, n1, lo0, hi0);
    for (o = 0; n0 && o < BALLS; o++) {
        const float *q = b1[SENT[o]];
        if (!(n1 >> o & 1u)) continue;
        for (i = 0; i < BALLS; i++) {
            const float *p = b0[SENT[i]];
            float dx, dy, dz, r, d2, ov;
            if (!(n0 >> i & 1u)) continue;
            dx = p[0] - q[0], dy = p[1] - q[1], dz = p[2] - q[2];
            r = b0[i][3] + b1[o][3], d2 = dx * dx + dy * dy + dz * dz;
            if (d2 >= r * r) continue;
            pairs++;
            ov = (z >> i & 1u) && (z >> o & 1u) ? 0.0f : r - sqrt_r(d2);
            if (ov > best) best = ov;
        }
    }
    vf2_push_pairs = pairs;
    out.f = kind == 4u || kind == 5u ? 0.0f : best;
    return out.u;
}

/* The contacts VF2's collision reads (its 0x238F8): the TGP's matrix of
 * every pair (1P's ball i, 2P's ball o) that meets, TGP-paired as above,
 * folded to units, table[UNIT[i]] bit UNIT[o]. A pair with 2P's ball in 2P's
 * attack mask, or 1P's in 1P's, is swept (TGP 0x8A5): it meets if the line
 * from last frame's R (2P's ball less 1P's) to this frame's passes within
 * r_i + r_o of 0; any other pair meets if this frame's |R| is under it.
 * StF's SHARC table pairs the balls its own way and puts a jab on a leg
 * where VF2 has none. VF2's TGP works on the balls of the step before; so
 * does the board here, its balls made before the fighters step.
 *
 * 900 pairs in floating point cost the i960 frames, so each pair is first
 * tried in whole numbers (1/1024 of a unit, a unit's slack each way): an
 * axis that keeps the two apart drops it. */
static float last_balls[2][BALLS][3];

/* |the point nearest 0 on the line from a to a + v|, squared (TGP 0x8A5). */
static float line_d2(const float *a, const float *v) {
    float av = a[0] * v[0] + a[1] * v[1] + a[2] * v[2];
    float vv = v[0] * v[0] + v[1] * v[1] + v[2] * v[2], t, p[3];
    u32 k;
    if (av >= 0.0f) t = 0.0f;
    else if (vv <= -av) t = 1.0f;
    else t = -av / vv;
    for (k = 0; k < 3; k++) p[k] = a[k] + t * v[k];
    return p[0] * p[0] + p[1] * p[1] + p[2] * p[2];
}

/* A fighter's TGP balls in whole numbers: lo and hi on each axis over this
 * frame's place and last frame's (sw), this frame's alone (st), the radius;
 * and each unit's box (its balls' sw boxes, each grown by its radius). */
typedef struct { int sw[2][3], st[2][3], r; } fix_ball;
typedef struct { fix_ball b[BALLS]; int u[16][2][3]; } fix_rob;
static fix_rob fx[2];   /* not on StF's stack: it is small */
/* The first TGP ball of each unit (1..15) and one past its last. */
static const u8 UNIT_FROM[17] = { 0, 0, 2, 3, 5, 7, 8, 10, 12, 13, 14, 17, 20, 22, 25, 28, 30 };

/* v x 1024 in whole numbers (toward 0), from the float's bits: the i960's
 * own conversion, with its constants in fp0..fp2, cost the board frames.
 * Out of range (or not a number) it is held at +-2^20. */
static int fix(float v) {
    union { float f; u32 u; } b;
    u32 e, m;
    int x;
    b.f = v, e = b.u >> 23 & 0xFFu, m = (b.u & 0x7FFFFFu) | 0x800000u;
    if (e >= 137u) x = 1 << 20;
    else if (e < 117u) x = 0;
    else x = (int)(m >> (140u - e));   /* v = m x 2^(e - 150) */
    return b.u >> 31 ? -x : x;
}

static void fix_balls(const float (*b)[4], const float (*l)[3], fix_rob *f) {
    u32 k, a, u;
    for (u = 1; u < 16; u++)
        for (a = 0; a < 3; a++) f->u[u][0][a] = 0x7FFFFFFF, f->u[u][1][a] = -0x7FFFFFFF;
    for (k = 0; k < BALLS; k++) {
        const float *p = b[SENT[k]], *q = l[SENT[k]];
        fix_ball *x = &f->b[k];
        int (*bx)[3] = f->u[UNIT[k]];
        x->r = fix(b[k][3]) + 1;
        for (a = 0; a < 3; a++) {
            int c = fix(p[a]), d = fix(q[a]);
            x->st[0][a] = c - 1, x->st[1][a] = c + 1;
            x->sw[0][a] = (c < d ? c : d) - 1, x->sw[1][a] = (c < d ? d : c) + 1;
            if (x->sw[0][a] - x->r < bx[0][a]) bx[0][a] = x->sw[0][a] - x->r;
            if (x->sw[1][a] + x->r > bx[1][a]) bx[1][a] = x->sw[1][a] + x->r;
        }
    }
}

/* Whether boxes x and y, each grown by part of ir, can meet. */
static int boxes_meet(const int (*x)[3], const int (*y)[3], int ir) {
    return y[0][0] - x[1][0] < ir && x[0][0] - y[1][0] < ir &&
           y[0][1] - x[1][1] < ir && x[0][1] - y[1][1] < ir &&
           y[0][2] - x[1][2] < ir && x[0][2] - y[1][2] < ir;
}

/* Whether 1P's ball i meets 2P's ball o (see above). */
static int balls_meet(const float (*b0)[4], const float (*b1)[4], u32 i, u32 o, u32 swept) {
    const float *p = b0[SENT[i]], *q = b1[SENT[o]];
    float rel[3], v[3], r = b0[i][3] + b1[o][3], d2;
    u32 a;
    for (a = 0; a < 3; a++) rel[a] = q[a] - p[a];
    if (swept) {
        const float *lp = last_balls[0][SENT[i]], *lq = last_balls[1][SENT[o]];
        for (a = 0; a < 3; a++) v[a] = rel[a], rel[a] = lq[a] - lp[a], v[a] -= rel[a];
        d2 = line_d2(rel, v);
    } else d2 = rel[0] * rel[0] + rel[1] * rel[1] + rel[2] * rel[2];
    return d2 < r * r;
}

void vf2_contacts(const u8 *rob0, const u8 *rob1, u32 *table) {
    const float (*b0)[4] = (const float (*)[4])(rob0 + 0xD00);
    const float (*b1)[4] = (const float (*)[4])(rob1 + 0xD00);
    u32 m0 = attack_mask(rob0), m1 = attack_mask(rob1), i, o, u, w, a;
    for (i = 0; i < 16; i++) table[i] = 0u;
    fix_balls(b0, (const float (*)[3])last_balls[0], &fx[0]);
    fix_balls(b1, (const float (*)[3])last_balls[1], &fx[1]);
    for (u = 1; u < 16; u++)
        for (w = 1; w < 16; w++) {
            if (!boxes_meet((const int (*)[3])fx[0].u[u], (const int (*)[3])fx[1].u[w], 0)) continue;
            for (i = UNIT_FROM[u]; i < UNIT_FROM[u + 1]; i++)
                for (o = UNIT_FROM[w]; o < UNIT_FROM[w + 1]; o++) {
                    u32 swept = (m1 >> o & 1u) | (m0 >> i & 1u);
                    const fix_ball *x = &fx[0].b[i], *y = &fx[1].b[o];
                    if (!boxes_meet(swept ? (const int (*)[3])x->sw : (const int (*)[3])x->st,
                                    swept ? (const int (*)[3])y->sw : (const int (*)[3])y->st,
                                    x->r + y->r) ||
                        !balls_meet(b0, b1, i, o, swept)) continue;
                    table[u] |= 1u << w;
                    goto next_unit;
                }
        next_unit:;
        }
    for (i = 0; i < BALLS; i++)
        for (a = 0; a < 3; a++) last_balls[0][i][a] = b0[i][a], last_balls[1][i][a] = b1[i][a];
}

board/src/fight/replay.c:
/*
 * replay.c — Fighting Vipers' replay of an armour break (REP_WAZA), which
 * StF kept: the watch on the breaking moves, the two passes from the
 * recorder's ring, and FV's replay camera.
 */
#include "megamix.h"

/* FV's replay of an armour break (rep_start): its task, whether it runs,
 * the camera's mode, each fighter's kind2 a frame ago */
u32 stf_play[0x100 / 4] __attribute__((aligned(16)));
u32 rep_on;
static u32 rep_mode, rep_prev[2], rep_mark[2], rep_pend;
static short rep_time[2];

/* Fighting Vipers' replay of an armour break, which StF kept as REP_WAZA
 * (sub_mode 22, its 0x11943FF on): twice, from two of FV's views, the
 * breaking move again from its start, the HUD hidden, then the fight on
 * from where it was.
 * - The recorder: rec_disp, a fight frame's last task, puts both fighters
 *   (their places, motions, frames and the frame's sounds, which
 *   check_same_sound keeps, four a frame) in a ring of 240 frames at
 *   0x535000; stf_rec +0x6C is the next one.
 * - The trigger, as FV's FIGHT_DSP (its 0xD5FC) watches each fighter's
 *   kind2: a breaking move's start (MK2_REPLAY rises) marks the ring's place
 *   and the clock (rep_mark); a break it deals (MK2_REPLAY_INIT, damage_unit's,
 *   lift-stf.py) leaves the replay pending, which starts once the move is
 *   over (MK2_REPLAY falls), P1's first.
 * - The replay (rep_start, rep_step): StF's sub_3900C starts a pass from
 *   the mark and keeps the effects aside (sub_3A200); replay_waza_disp
 *   puts a frame back a frame, with its sounds, and at the ring's place
 *   the replay started from puts the fighters where they were and the
 *   effects back. Each pass the clock goes back to the mark's.
 * - The camera is FV's (its camera modes 0x11, 0x12 and 0x13, rep_cam;
 *   StF's own 0xF and 0x10 follow the round's winner instead): a view
 *   from rep_view (FV's two tables of eight, tools/board/bake-board.mjs) picked
 *   at random, the next one for the second pass, turned and raised to
 *   look at the fighters; then it slides after the point between them
 *   (or the breaker, MK2_PIKA), at a distance that grows with theirs.
 *   FV's 0x513830 on its yaw is its g3, left over from the code before
 *   (the same in every replay, MAME).
 * - The HUD: REP_WAZA's window mask shows tile layer 1, cleared, in place
 *   of layer 0's HUD; FV's over its top 96 lines, the board's over the
 *   whole screen, StF's barrier boxes at the bottom too. */
#define SUB_REP_WAZA  22u
#define CAM_AT        0x120u     /* f32 x3 what the camera looks at */
#define CAM_VIEW      0x210u     /* u32 the view, 0..7 */
#define CAM_KEPT_POS  0x318u     /* REP_WAZA's copy of +0x18, +0x120 (+0x324) and the angles (+0x330) */
#define CAM_KEPT_AT   0x324u
#define CAM_KEPT_ANG  0x330u
#define CAM_DIST      0x338u     /* f32 the view's distance */
#define CAM_HIGH      0x344u     /* f32 the view's height */
#define CAM_MODE_REP  0x11u      /* FV's: a view from table 0; 0x12 table 1; 0x13 following */
#define FV_REP_YAW    0x3830u
#define FV_UNIT       (2.676f / 1.309f)
#define COP_ATAN2F    COP_CMD(0x27)  /* in: a, b; out: i16 the angle of (a, b) */

static u32 cop_angle(u32 op, float a, float b, float c, float d, u32 n) {
    volatile u32 *cf = (volatile u32 *)M2_COPFIFO_ADDR;
    *cf = op; *cf = m2_obj_fb(a); *cf = m2_obj_fb(b);
    if (n == 4u) { *cf = m2_obj_fb(c); *cf = m2_obj_fb(d); }
    return *cf;
}

static float rep_f(u32 u) { union { u32 u; float f; } x; x.u = u; return x.f; }

/* what the replay looks at (FV's 0x67444): each fighter's root (on the
 * ground while its motion has MK_MOVE), at its ground's height when it is
 * down (MK_DOWN_POSE, MK_DOWN, MK_AIR), else 0.9 over its feet; the point
 * between them, or the breaker's own with MK2_PIKA */
static void rep_target(float t[3], float g[2][3]) {
    u32 p, k;
    for (p = 0; p < 2u; p++) {
        u32 *r = robs[p], mk = RW(r, ROB_MOT_KIND);
        u32 o = mk & MK_MOVE ? ROB_GXPOS : ROB_XPOS;
        g[p][0] = *(float *)&RW(r, o);
        g[p][2] = *(float *)&RW(r, o + 8u);
        g[p][1] = mk & (MK_DOWN_POSE | MK_DOWN | MK_AIR) ? *(float *)&RW(r, ROB_GXPOS + 4u)
                                                       : *(float *)&RW(r, ROB_YPOS) + 0.9f * FV_UNIT;
    }
    p = RAM8(G_REP_FLAG) >> 2 & 1u;
    for (k = 0; k < 3u; k++)
        t[k] = RW(robs[p], ROB_KIND2) & MK2_PIKA ? g[p][k] : (g[0][k] + g[1][k]) * 0.5f;
}

/* FV's replay camera: mode 0x11 or 0x12 sets the view up, 0x13 follows */
static void rep_cam(void) {
    volatile u32 *cf = (volatile u32 *)M2_COPFIFO_ADDR;
    float t[3], g[2][3], *at = (float *)&RW(stf_cam, CAM_AT), d;
    u32 k;
    rep_target(t, g);
    if (rep_mode != 0x13u) {
        const float *v = rep_view[rep_mode - CAM_MODE_REP][RW(stf_cam, CAM_VIEW)];
        for (k = 0; k < 3u; k++) at[k] = t[k];
        RH(stf_cam, CAMERA_YANG) = (u16)(cop_angle(COP_ATAN2, 0.0f, v[2], v[0], 0.0f, 4u) + FV_REP_YAW);
        d = rep_f(cop_angle(COP_DIST2D, 0.0f, v[0], 0.0f, v[2], 4u));
        *(float *)&RW(stf_cam, CAM_DIST) = d;
        RH(stf_cam, CAMERA_XANG) = (u16)cop_angle(COP_ATAN2F, d, v[1], 0.0f, 0.0f, 2u);
        *(float *)&RW(stf_cam, CAM_HIGH) = v[1];
        rep_mode = 0x13u;
    }
    for (k = 0; k < 3u; k++) at[k] += (t[k] - at[k]) * 0.05f;
    d = rep_f(cop_angle(COP_DIST2D, g[0][0], g[1][0], g[0][2], g[1][2], 4u));
    if (d < 2.0f * FV_UNIT) d = 2.0f * FV_UNIT;
    d = d * 0.717f + 2.0f * FV_UNIT;
    RH(stf_cam, CAMERA_XANG) = (u16)cop_angle(COP_ATAN2F, d, t[1] - *(float *)&RW(stf_cam, CAM_HIGH), 0.0f, 0.0f, 2u);
    *cf = COP_PUSH;
    *cf = COP_IDENTITY;
    *cf = COP_SET_POS; *cf = m2_obj_fb(at[0]); *cf = m2_obj_fb(at[1]); *cf = m2_obj_fb(at[2]);
    *cf = COP_ANG_Y; *cf = (u32)(int)(short)RH(stf_cam, CAMERA_YANG);
    *cf = COP_ANG_X; *cf = (u32)(int)(short)RH(stf_cam, CAMERA_XANG);
    *cf = COP_M2W; *cf = 0u; *cf = 0u; *cf = m2_obj_fb(-d);
    for (k = 0; k < 3u; k++) RW(stf_cam, CAMERA_XPOS + 4u * k) = *cf;
    *cf = COP_POP;
}

/* a pass: the clock back to the mark's, the play task from the mark */
static void rep_pass(void) {
    GAME_TIMER = rep_time[RAM8(G_REP_FLAG) >> 2 & 1u];
    RAM32(G_REP_MARK0) = rep_mark[0];
    RAM32(G_REP_MARK1) = rep_mark[1];
    task_reset(stf_play, sizeof stf_play);
    stf_task(stf_sub_3900C, stf_play, robs[0], robs[1]);
}

static void rep_start(u32 p) {
    u32 i;
    RAM8(G_REP_FLAG) = (u8)(p << 2);
    RAM8(G_REP_PASSES) = 2u;
    /* both: set_mot_dat marks each motion's start in FIGHT_DSP only */
    RAM8(G_SUB_MODE) = RAM8(G_SUB_MODE + 1u) = SUB_REP_WAZA;
    for (i = 0; i < 3u; i++) {
        RW(stf_cam, CAM_KEPT_POS + 4u * i) = RW(stf_cam, CAMERA_XPOS + 4u * i);
        RW(stf_cam, CAM_KEPT_AT + 4u * i) = RW(stf_cam, CAM_AT + 4u * i);
        RH(stf_cam, CAM_KEPT_ANG + 2u * i) = RH(stf_cam, CAMERA_XANG + 2u * i);
    }
    i = frame_counter * 0x41C64E6Du + 12345u;
    RW(stf_cam, CAM_VIEW) = (i >> 16) & (cur_stage && (cur_stage->slot == 3u || cur_stage->slot == 6u) ? 3u : 7u);
    rep_mode = CAM_MODE_REP;
    for (i = 0; i < 64u * 48u; i++) TILE_L1[i] = 0x8020u;
    for (i = 0; i < 384u * 4u; i++) TILE_MASK[i] = 0xFFFFu;
    rep_on = 1u;
    rep_pass();
}

void rep_quit(void) {
    u32 i;
    for (i = 0; i < 2u; i++) RW(robs[i], ROB_KIND2) &= ~MK2_REPLAY_INIT;
    rep_pend = 0u;
    RW(stf_cam, CAMERA_FLAG) &= ~CAMERA_F_REPLAY;
    for (i = 0; i < 3u; i++) {
        RW(stf_cam, CAMERA_XPOS + 4u * i) = RW(stf_cam, CAM_KEPT_POS + 4u * i);
        RW(stf_cam, CAM_AT + 4u * i) = RW(stf_cam, CAM_KEPT_AT + 4u * i);
        RH(stf_cam, CAMERA_XANG + 2u * i) = RH(stf_cam, CAM_KEPT_ANG + 2u * i);
    }
    RW(stf_cam, CAMERA_FLAG) |= CAMERA_ROB0_DISP | CAMERA_ROB1_DISP;
    RAM8(G_SUB_MODE) = RAM8(G_SUB_MODE + 1u) = SUB_FIGHT_DSP;
    for (i = 0; i < 384u * 4u; i++) TILE_MASK[i] = 0u;
    rep_on = 0u;
}

/* a 60 Hz frame of the replay: the play task's frame, the effects, the
 * camera; a pass over, the next from the other table, or the fight */
void rep_step(void) {
    stf_task((void (*)(void))RW(stf_play, TASK_FN), stf_play, robs[0], robs[1]);
    stf_task((void (*)(void))RW(stf_effect, TASK_FN), stf_effect, robs[0], robs[1]);
    rep_cam();
    RH(stf_cam, CAMERA_CNT)++;
    if (RW(stf_play, TASK_FLAG) & TASK_ALIVE) return;
    if (--RAM8(G_REP_PASSES) == 0u) { rep_quit(); return; }
    rep_mode = CAM_MODE_REP + 1u;
    RW(stf_cam, CAM_VIEW) = (RW(stf_cam, CAM_VIEW) + 1u) & 7u;
    rep_pass();
}

/* FV's FIGHT_DSP's watch on the breaking moves; 1 once a replay starts.
 * Its marks and pending bits are the board's own: StF's set_mot_dat marks
 * (G_REP_MARK0, G_REP_TIME) and clears the bits at every motion's start,
 * the one that ends the breaking move too. */
u32 rep_watch(void) {
    u32 p, k[2];
    for (p = 0; p < 2u; p++) {
        k[p] = RW(robs[p], ROB_KIND2);
        if (k[p] & MK2_REPLAY_INIT) rep_pend |= 1u << p;
        if ((k[p] & ~rep_prev[p]) & MK2_REPLAY) {
            rep_mark[p] = RW(stf_rec, REC_NEXT);
            rep_time[p] = GAME_TIMER;
            rep_pend &= ~(1u << p);
        }
    }
    for (p = 0; p < 2u; p++) {
        u32 fell = (rep_prev[p] & ~k[p]) & MK2_REPLAY;
        rep_prev[p] = k[p];
        if (fell && (rep_pend & 1u << p) && !rep_on) rep_start(p);
    }
    return rep_on;
}

/* a round's start: no replay */
void rep_round(void) {
    rep_on = rep_prev[0] = rep_prev[1] = rep_pend = 0u;
    RAM8(G_REP_FLAG) = 0u;
}

/* a match from the boot state: no marks, no clocks */
void rep_forget(void) {
    rep_mark[0] = rep_mark[1] = 0u;
    rep_time[0] = rep_time[1] = 0;
}

board/src/fight/ringout.c:
/*
 * ringout.c — VF2's ring out on its stages: a fighter past the ring's edge
 * falls, and loses the round once he lands outside it.
 */
#include "megamix.h"

/* each fighter's frames since its root left the ring (0: inside) */
static u32 rout[2];
u32 ring_out;
static u32 rout_vy[2];            /* its fall's speed, a float's bits */

/* a round's start: both inside */
void ring_out_reset(void) {
    rout[0] = rout[1] = ring_out = 0u;
    rout_vy[0] = rout_vy[1] = 0u;
}

/*
 * VF2's ring out (checked in its program, Ghidra and objdump): once a frame
 * the fighter's root (rob part 0, +0x1F4 x and +0x1FC z) against stage_x
 * (0x50A00C, 8.0 at the default ring size, from 0x11530): at |x| or |z| at
 * or past it the fighter falls (0x17BA8) to the ground outside (0x50A010,
 * -0.5); once a collision ball outside the ring touches that ground (rob
 * +0x624, area_coli 0x2396C, about 18 frames from standing) rob_check_stage
 * (0x17BC0) sets w0 bit 5, a knock-out's bit, and JUDGE_DSP_INT (0xE5A8)
 * calls it a ring out (0x500050) while both energies are above 0; the
 * round goes to the one whose bit 5 is clear. StF has the same code with
 * the bit set left out (rob_check_stage 0x181D8) and walls instead, so the
 * board does it here: the ring, the drop and the ground in StF's units
 * (VF2's times the guests' scale), the bit after VF2's 18 frames.
 */
#define RING_OUT_FRAMES 18u
/* float order on the bits (the board has no float compares) */
static u32 f_key(u32 u) { return u & 0x80000000u ? ~u : u | 0x80000000u; }
static u32 f_add(u32 a, u32 b) {
    volatile u32 *cf = (volatile u32 *)M2_COPFIFO_ADDR;
    *cf = COP_FADD; *cf = a; *cf = b;
    return m2_obj_fb(m2_cop_gf());
}

void ring_out_step(const stage_t *st) {
    u32 p, ring = m2_obj_fb(st->ring), ground = m2_obj_fb(-0.5f * VF2_SCALE);
    u32 g = RAM32(G_GRAVITY) ^ 0x80000000u;   /* -gravity */
    if (ring == 0u) return;
    for (p = 0; p < 2u; p++) {
        u32 *r = robs[p], y;
        if (!rout[p]) {
            if ((RW(r, ROB_GXPOS) & 0x7FFFFFFFu) < ring && (RW(r, ROB_GZPOS) & 0x7FFFFFFFu) < ring) continue;
            rout_vy[p] = 0u;
        }
        rout_vy[p] = f_add(rout_vy[p], g);
        y = f_add(RW(r, ROB_YPOS), rout_vy[p]);
        RW(r, ROB_YPOS) = f_key(y) < f_key(ground) ? ground : y;
        if (++rout[p] == RING_OUT_FRAMES) {
            if ((short)RH(robs[0], ROB_ENERGY) > 0 && (short)RH(robs[1], ROB_ENERGY) > 0) ring_out = 1u;
            RW(r, ROB_FLAG) |= ROB_F_LOST;
        }
    }
}

/* RING OUT, over the 3D while the round ends */
#define MSG_COL 27u
#define MSG_ROW 12u
void ring_msg(u32 on) {
    u32 y, c;
    put_at(MSG_COL, MSG_ROW, on ? "RING OUT" : "        ", on ? T_INV : 0x8020u);
    if (on) { mask_rect(MSG_COL, MSG_ROW, 8u, 1u); return; }
    for (y = MSG_ROW * 8u; y < MSG_ROW * 8u + 8u; y++)
        for (c = MSG_COL; c < MSG_COL + 8u; c++) TILE_MASK[y * 4u + (c >> 4)] &= (u16)~(0x8000u >> (c & 15u));
}

board/src/link/link.c:
/*
 * link.c — the Model 2 communication board, and two boards in step over it.
 *
 * The comm board (837-11615 on Model 2B, MAME m2comm.cpp) is a Z80 with 16 KB
 * of RAM the i960 shares, and two registers:
 *
 *   0x01A10000  shared RAM (also at 0x01A00000; Virtual-On and Motor Raid use
 *               this mirror)
 *     +0x00     the ring: 1 up (0 not yet, 0xFF failed)
 *     +0x01     the cabinet's role, which the program writes once the board
 *               runs: 1 master, 2 slave (the board's reset value)
 *     +0x02     this node's id, +0x03 the nodes on the ring, once it is up
 *     +0x12     the frame size, +0x14 the frame offset (0x1C0), little-endian
 *     +0x2000   this node's frame: the Z80 sends the frame offset's bytes
 *               from here, once a vblank
 *     +0x2000 + offset
 *               the frame the Z80 took from the node one hop up the ring, the
 *               other board's on a ring of two
 *   0x01A14000  CN: 1 starts the board (the RAM cleared, the ring brought
 *               up), 0 stops it. A board reads bit 0 back as written; with no
 *               board the bus reads all ones (Motor Raid's checkBoard:
 *               "Nothing Communication Board!")
 *   0x01A14002  FG: bit 0 written 1 also makes a master (EPR-16726); bit 7
 *               toggles as frames come in
 *
 * The ring: once both boards run, the master waits about four seconds, then
 * sends its id token round the ring, and each node writes +0 = 1, its id and
 * the count. From then on, every vblank the master sends its frame and the
 * slave answers each frame it takes with its own. The frame the other board
 * sent stays in the RAM until the next replaces it.
 *
 * That transport is what Virtual-On and Motor Raid build on (m2-hle2
 * src/board/m2comm.h, YAMP's von-comm-packet.md and mr-comm-packet.md): each
 * keeps a packet in its frame, stamped so a torn or stale one is told apart
 * (Virtual-On's seq ^ 0xAE5E, Motor Raid's alive counter), with the master's
 * settings in it for the slave to take. A fighting game needs both boards to
 * see the same pads on the same frame, so this one sends pads, not state: a
 * packet holds this cabinet's last LINK_HIST frames of pad (a frame lost or
 * read twice loses nothing), and each board steps a frame only once it holds
 * the other's pad for it (lockstep). Pads go out LINK_DELAY frames ahead of
 * their frame, so in the steady state neither waits. A check of each
 * stepped frame's state rides along: boards whose fights part (a desync) start
 * over from the master's setup.
 *
 * Packet, at 0x2000 (32-bit words):
 *   magic, state | role << 8 | hold << 16, session, known (the frames < known have pads),
 *   check_at (frames stepped), check (their state), in[LINK_HIST] (u16,
 *   in[t % LINK_HIST] the pad for frame t), set[LINK_SETS] (u16, the master's
 *   setup), sum (of everything before it)
 */
#include "link.h"

#define COMM_RAM   0x01A10000u
#define COMM_CN    (*(volatile unsigned char *)0x01A14000u)
#define COMM_FG    (*(volatile unsigned char *)0x01A14002u)
#define COMM_B(o)  (*(volatile unsigned char *)(COMM_RAM + (o)))
#define COMM_FRAME 0x2000u

#define LINK_MAGIC   0x4D4D5831u     /* "MMX1" */
#define LINK_TIMEOUT 300u            /* vblanks without the other's pads: the link is gone */
#define BACKUP_LINK  ((volatile lk_u32 *)0x01D03FF0u)   /* past StF's settings in the backup RAM */

typedef struct {
    lk_u32 magic, head, session, known, check_at, check;
    lk_u16 in[LINK_HIST];
    lk_u16 set[LINK_SETS];
    lk_u32 sum;
} pkt_t;

#define PKT_WORDS (sizeof(pkt_t) / 4u)

link_t link;
static pkt_t out, peer;                      /* this board's packet, the other's last good one */
static lk_u32 checks[LINK_HIST];             /* this board's checks, by frame */

static lk_u32 pkt_sum(const pkt_t *p) {
    const lk_u32 *w = (const lk_u32 *)p;
    lk_u32 s = LINK_MAGIC, i;
    for (i = 0; i < PKT_WORDS - 1u; i++) s = (s ^ w[i]) * 0x01000193u + (s >> 15);
    return s;
}

static lk_u32 frame_offset(void) {
    lk_u32 o = COMM_B(0x14) | (lk_u32)COMM_B(0x15) << 8;
    return o >= sizeof(pkt_t) && o <= 0x1000u ? o : 0x1C0u;
}

static void pkt_send(void) {
    volatile lk_u32 *d = (volatile lk_u32 *)(COMM_RAM + COMM_FRAME);
    const lk_u32 *s = (const lk_u32 *)&out;
    lk_u32 i;
    out.magic = LINK_MAGIC;
    out.sum = pkt_sum(&out);
    for (i = 0; i < PKT_WORDS; i++) d[i] = s[i];
}

/* The other board's packet, if one is there whole and is the other role's:
 * the Z80 may write a frame while it is read, so a read that does not add
 * up is tried again. */
static lk_u32 pkt_take(void) {
    volatile lk_u32 *s = (volatile lk_u32 *)(COMM_RAM + COMM_FRAME + frame_offset());
    pkt_t p;
    lk_u32 *d = (lk_u32 *)&p, i, k;
    for (k = 0; k < 3u; k++) {
        for (i = 0; i < PKT_WORDS; i++) d[i] = s[i];
        if (p.magic != LINK_MAGIC || p.sum != pkt_sum(&p)) continue;
        /* a ring of one hands a node its own frame back */
        if ((p.head >> 8 & 0xFFu) == link.role) break;
        peer = p;
        return 1u;
    }
    link.bad++;
    return 0u;
}

lk_u32 link_board(void) {
    COMM_CN = 0u;
    return !(COMM_CN & 1u);
}

void link_start(lk_u32 role) {
    lk_u32 i;
    COMM_CN = 0u;
    COMM_FG = 0u;
    link.role = role;
    link.session = link.tick = link.done = 0u;
    for (i = 0; i < PKT_WORDS; i++) ((lk_u32 *)&out)[i] = ((lk_u32 *)&peer)[i] = 0u;
    if (role == LINK_OFF) { link.state = LS_OFF; return; }
    if (!link_board()) { link.state = LS_NO_BOARD; return; }
    COMM_CN = 1u;                            /* the RAM cleared, +1 = 2 (a slave) */
    COMM_B(1) = (unsigned char)role;
    COMM_FG = role == LINK_MASTER ? 1u : 0u;
    link.state = LS_WAIT;
}

/* The link gone: this board alone until a new session starts in step. A
 * ring that went down, or another board gone quiet, brings the comm board
 * up again (as Motor Raid's _ResetCommBoard does), for the ring to come up
 * once the other is back; boards that only parted (a desync) keep the ring. */
static lk_u32 drop(lk_u32 ring) {
    lk_u32 d = link.drops + 1u;
    if (ring) link_start(link.role);
    else {
        link.state = LS_HELLO;
        link.session = link.tick = link.done = 0u;
    }
    link.drops = d;
    return LP_DROP;
}

static void head(lk_u32 state) {
    out.head = state | link.role << 8 | (link.hold ? 1u : 0u) << 16;
    out.session = link.session;
}

lk_u32 link_pass(lk_u32 mine, lk_u16 set[LINK_SETS], lk_u32 in[2], lk_u32 now, void (*wait)(void)) {
    lk_u32 i, t, me = link.role == LINK_SLAVE;
    if (link.state <= LS_NO_BOARD) return LP_LOCAL;
    if (COMM_B(0) != 1u || COMM_B(3) < 2u) {
        lk_u32 was = link.state;
        link.state = COMM_B(0) == 1u ? LS_NO_PEER : LS_WAIT;
        return was == LS_RUN ? drop(1u) : LP_LOCAL;
    }
    if (link.state < LS_HELLO) {
        link.state = LS_HELLO;
        link.session = 0u;
    }
    if (link.state == LS_HELLO) {
        lk_u32 got = pkt_take();
        if (link.role == LINK_MASTER) {
            if (!link.session) link.session = (now * 0x9E3779B9u ^ link.drops << 24) | 1u;
            for (i = 0; i < LINK_SETS; i++) out.set[i] = set[i];
            head(LS_HELLO);
            pkt_send();
            /* both boards free: the slave has the session and is not busy */
            if (!got || peer.session != link.session || link.hold || (peer.head >> 16 & 1u)) return LP_LOCAL;
        } else {
            if (got && peer.session) {
                if ((peer.head & 0xFFu) == LS_RUN && peer.session == link.session) {
                    for (i = 0; i < LINK_SETS; i++) set[i] = peer.set[i];
                } else link.session = peer.session;
            }
            head(LS_HELLO);
            pkt_send();
            if (!got || (peer.head & 0xFFu) != LS_RUN || peer.session != link.session) return LP_LOCAL;
        }
        /* in step from frame 0: the first LINK_DELAY frames have no pads */
        link.state = LS_RUN;
        link.tick = link.done = 0u;
        link.since = now;
        for (i = 0; i < LINK_HIST; i++) out.in[i] = 0u;
        out.known = LINK_DELAY;
        out.check_at = 0u;
        head(LS_RUN);
        pkt_send();
        return LP_SYNC;
    }

    /* in step: this pad for frame t + LINK_DELAY, then the other's for t */
    t = link.tick;
    out.in[(t + LINK_DELAY) % LINK_HIST] = (lk_u16)mine;
    out.known = t + LINK_DELAY + 1u;
    head(LS_RUN);
    pkt_send();
    for (;;) {
        if (pkt_take()) {
            if (peer.session != link.session) return drop(0u);
            if ((peer.head & 0xFFu) == LS_RUN && peer.known > t) break;
        }
        if (COMM_B(0) != 1u || now - link.since > LINK_TIMEOUT) return drop(1u);
        wait();
        now++;
        link.stalls++;
    }
    link.since = now;
    /* the other's check of a frame this board has stepped too */
    if (peer.check_at && peer.check_at <= link.done && link.done - peer.check_at < LINK_HIST &&
        peer.check != checks[(peer.check_at - 1u) % LINK_HIST]) {
        link.desyncs++;
        return drop(0u);
    }
    in[me] = out.in[t % LINK_HIST];
    in[me ^ 1u] = peer.in[t % LINK_HIST];
    link.tick = t + 1u;
    return LP_TICK;
}

void link_check(lk_u32 sum) {
    if (link.state != LS_RUN) return;
    checks[link.done % LINK_HIST] = sum;
    link.done++;
    out.check_at = link.done;
    out.check = sum;
}

lk_u32 link_saved(void) {
    lk_u32 r = BACKUP_LINK[1];
    return BACKUP_LINK[0] == LINK_MAGIC && BACKUP_LINK[2] == ~r && r <= LINK_SLAVE ? r : LINK_OFF;
}

void link_save(lk_u32 role) {
    BACKUP_LINK[0] = LINK_MAGIC;
    BACKUP_LINK[1] = role;
    BACKUP_LINK[2] = ~role;
}

board/src/link/linkplay.c:
/*
 * linkplay.c — the two-cabinet link's side of the game (link.c runs the
 * comm board): the wait that keeps the sound going, the frame's checksum,
 * the setup the master hands the slave, and the boot's communication check.
 */
#include "megamix.h"

/* link.c's wait for the other board: a vblank, sending the sound meanwhile */
void link_wait(void) {
    u32 v = frameVBL;
    while (frameVBL == v) snd_pump();
}

/* The state a linked frame leaves, for link_check: both fighters' records,
 * StF's clock and random number, the setup and the match. */
u32 link_sum(u32 in_menu, u32 over) {
    u32 i, p, s = 0x811C9DC5u;
    for (p = 0; p < 2u; p++)
        for (i = 0; i < ROB_SIZE / 4u; i++) s = (s ^ robs[p][i]) * 0x01000193u;
    for (i = 0; i < M_LINK; i++) s = (s ^ menu_val[i]) * 0x01000193u;
    s = (s ^ menu_cur ^ in_menu << 8 ^ over << 16) * 0x01000193u;
    s = (s ^ (u16)GAME_TIMER ^ (u32)RAM8(G_ROUND_WINS0) << 16 ^ (u32)RAM8(G_ROUND_WINS1) << 24) * 0x01000193u;
    return (s ^ RAM32(G_RANDOM)) * 0x01000193u;
}

/* The setup's values the master hands the slave, and its cursor */
void link_set(lk_u16 set[LINK_SETS]) {
    u32 i;
    for (i = 0; i < LINK_SETS; i++) set[i] = i < M_LINK ? menu_val[i] : 0u;
    set[M_START] = (u16)menu_cur;
}

/* The boot's watchdog: with a role kept (the setup's LINK) and a comm board
 * that answers, wait up to LINK_BOOT_WAIT for the other cabinet, as a
 * linked game's communication check does. LP_SYNC: the boards are linked
 * (set the master's setup). Else this board boots alone: on a press of
 * start, once the wait runs out, or at once with no role or no board. It
 * links later from the setup (both boards in it), as the other cabinet
 * comes up. */
u32 link_boot(lk_u16 set[LINK_SETS]) {
    u32 t0 = frameVBL, t, lp;
    lk_u32 in[2];
    char b[8];
    if (link.state <= LS_NO_BOARD) return LP_LOCAL;
    while ((t = frameVBL - t0) < LINK_BOOT_WAIT) {
        const char *d = dec((LINK_BOOT_WAIT - t + 59u) / 60u, b);
        win_frame(WIN_COL, WIN_ROW, WIN_W, 6u);
        win_put(1, 1, "COMMUNICATION_CHECK", T_INV);
        win_put(3, 2, "CABINET", T_TEXT);
        win_put(WIN_W - 2u - slen(link_name[link.role]), 2, link_name[link.role], T_INV);
        win_put(3, 3, link_state_name[link.state], T_TEXT);
        win_put(WIN_W - 2u - slen(d), 3, d, T_INV);
        win_put(3, 4, "START:SINGLE_BOARD", T_TEXT);
        link_set(set);
        lp = link_pass(0u, set, in, frameVBL, link_wait);
        if (lp == LP_SYNC) return lp;
        if (m2_player(0).start || m2_player(1).start) break;
        link_wait();
    }
    return LP_LOCAL;
}

board/src/main.c:
/*
 * main.c — the board's frame loop.
 *
 * The boot (boot_board) sets the board, StF's globals and the setup menu up
 * and links to the other cabinet if there is one. Then, once a vsync: the
 * pads (through the link when the boards are linked), the setup menu or the
 * fight's inputs, the scene's stage (scene_begin), the fight stepped a 60 Hz
 * frame for every vblank since the last pass (fight_frame: the round's end,
 * the ring out, the replay), the fighters and the effects (scene_end), and
 * the wait for the vsync, sending the sound meanwhile (vsync_wait).
 *
 * A match: match_start from the setup, round_judge when a round is decided,
 * round_end three seconds later (the next round, or the setup once the
 * match is won), match_reset when the boards link or part.
 */
#include "megamix.h"

/* StF's frame_counter; the frame loop copies it to 0x500020, where StF's
 * code (sub_2435C's colour cycling) reads it. */
u32 frame_counter;

static fighter_t fs[2];                  /* the fighters, as the setup picks them */
static lk_u16 set[LINK_SETS];            /* the setup, as the link carries it */
static u32 stage;                        /* the stage's number (stages[], the setup's) */
u32 in_menu = 1u;                        /* the setup menu is up (in the map: tools/mame/battle.lua) */
static u32 over;                         /* the round is decided: frames to the next */
static u32 judging;                      /* its end found: steps to JUDGE_DSP_INT */
static u32 quit;                         /* both starts: back to the setup */
static u32 held, pheld;                  /* the starts and pads held last frame (edges) */
static u32 step;                         /* frame_counter at the last fight step */
static u32 vbl;                          /* frameVBL at the last vsync */
static u32 pn[3];                        /* the faces drawn: the stage's, each fighter's */

static u32 pad_bits(const m2_player_t *p) {
    return (u32)p->b1 | (u32)p->b2 << 1 | (u32)p->b3 << 2 | (u32)p->down << 4 |
           (u32)p->up << 5 | (u32)p->right << 6 | (u32)p->left << 7;
}

static u32 edges(u32 now, u32 *last) { u32 e = now & ~*last; *last = now; return e; }

/* StF's blank front layer (clr_pattern_s), the setup's window over it */
static void menu_open(void) {
    u32 i;
    in_menu = 1u;
    for (i = 0; i < 64u * 64u; i++) M2_TILE_FG[i] = 0x20u;
    menu_mask(1u);
}

/* the setup's values into StF's globals, as a match starts on them */
static void setup_apply(void) {
    round_time = menu_val[M_TIME];
    RAM32(G_ENERGY_MAX) = menu_val[M_ENERGY];
    RAM32(G_BARRIER_DEFAULT) = menu_val[M_BARRIER];
    RAM8(G_WINS_NEEDED) = (u8)menu_val[M_ROUND];
    RAM8(G_ROUND_WINS0) = RAM8(G_ROUND_WINS1) = 0u;
}

/* The board as the boot leaves it: the SDK's init, the fighters' textures and
 * palettes, StF's globals, the first stage, StF's tiles, the setup menu
 * over the fighters in their stance, the fight's state kept (boot_state)
 * and the link's role from the backup RAM. Returns link_boot's pass. */
static u32 boot_board(void) {
    u32 i;
    m2_init();
    m2_silicon_boot();
    m2_sound_init();                     /* init_sound: the USART, then the sound program's reset */
    m2_cam_set_focus(FOCUS);
    camera_init();
    tex_load_set(SET_FIGHTERS);
    load_palettes();
    stf_globals();
    /* the test menu's monitor setting as the boot reads it: CRT, StF's
     * TST_* curve constants (load_COLORS_to_RAM, chg_scr_color_req) */
    stf_call(stf_set_display_type_crt, robs[0], robs[1], 0u);
    load_stage(stage);                   /* its fighters' colours once they are set up (round_start) */
    for (i = 0; i < 8u; i++) { m2_frame_begin(); m2_frame_end(); }

    stf_camera();
    /* StF's tiles and their colours: the set the boot loads (the clock's
     * digits, the bars, the debug font and frames), then the fight's, as
     * MES_ROUND_INT loads them */
    stf_call(stf__Scroll_Initialize, robs[0], robs[1], 0u);
    stf_call(stf__Scroll_Initialize, robs[0], robs[1], 70u);
    stf_call(stf__Scroll_Initialize, robs[0], robs[1], 170u);
    bg_col_set(cur_stage->bg);           /* scr_bg_int, after them: the stage's pen 0 again */
    for (i = 0; i < 64u * 64u; i++) M2_TILE_FG[i] = 0x20u;   /* StF's blank (clr_pattern_s) */
    menu_clear();
    menu_mask(1u);
    fs[0].anim = pose_anim(menu_val[M_P1]);
    fs[1].anim = pose_anim(menu_val[M_P2]);
    round_start(fs, 0u);
    load_fighter_colors(fs[0].anim, fs[1].anim);
    boot_state(1u);
    menu_val[M_LINK] = (u16)link_saved();
    link_start(menu_val[M_LINK]);
    return link_boot(set);
}

/* The boards linked (LP_SYNC: both from the same start, the master's setup
 * and its cursor) or parted (LP_DROP: this one alone again): the setup, the
 * fight's state as the boot left it, the clock counted from 0. */
static void match_reset(u32 lp) {
    u32 i;
    if (lp == LP_SYNC) {
        for (i = 1; i < M_LINK; i++) menu_val[i] = set[i];
        menu_cur = set[M_START] % M_ITEMS;
    }
    if (rep_on) rep_quit();
    boot_state(0u);
    rep_forget();
    armour_forget();
    stf_globals();
    frame_counter = step = 0u;
    RAM32(G_FRAME_COUNTER) = 0u;
    setup_apply();
    stage = menu_val[M_STAGE];
    load_stage(stage);
    fs[0].anim = pose_anim(menu_val[M_P1]);
    fs[1].anim = pose_anim(menu_val[M_P2]);
    menu_open();
    round_start(fs, 0u);
    stage_colors(cur_stage);
    load_fighter_colors(fs[0].anim, fs[1].anim);
    menu_ink(1u);
    snd_request_u(SND_RESET);
    over = judging = quit = held = pheld = 0u;
}

/* The setup window, on either pad: h its held pad bits, e the new start
 * presses. The fighters stand in their stance behind it, on the stage it
 * picks, with the clock held. */
static void menu_frame(u32 h, u32 e) {
    u32 c = menu_input(edges(h, &pheld), h, e & 3u), i;
    if (c == M_LINK) {
        /* this cabinet's role, a fresh start of its comm board;
         * linked, both boards see the press: both go alone */
        u32 r = link.state == LS_RUN ? LINK_OFF : menu_val[M_LINK];
        menu_val[M_LINK] = (u16)r;
        link_save(r);
        link_start(r);
    }
    if (c == M_STAGE) {
        stage = menu_val[M_STAGE];
        load_stage(stage);
        load_fighter_colors(fs[0].anim, fs[1].anim);   /* their bands, over the stage's rows */
        menu_ink(1u);
    }
    if (c == M_P1 || c == M_P2) {
        fs[c == M_P1 ? 0u : 1u].anim = pose_anim(menu_val[c]);
        /* both: player 2's character turns on whether it is player 1's */
        for (i = 0; i < 2u; i++) {
            rob_init(i, &fs[i]);
            rob_start(i);
            armour_limits(i);
        }
        /* the scene's rows again: a guest's seven part rows took StF's fixed ones */
        stage_colors(cur_stage);
        load_fighter_colors(fs[0].anim, fs[1].anim);
        menu_ink(1u);
    }
    if (c == M_START) {
        setup_apply();
        menu_clear();
        round_start(fs, 0u);
        snd_round(stage, cur_stage, 1u);
        over = judging = 0u;
        in_menu = 0u;
    } else {
        menu_draw();
        GAME_TIMER = (short)(round_time << 6);
    }
}

/* The round, as VF2's JUDGE_DSP_INT gives it: to the one whose bit 5 is
 * clear (a knock-out, a ring out), else to the one with more energy left.
 * Then StF's judging, for ko_disp and the rules that stop at the round's
 * end (attack_hit, damage_unit): also_sub_mode JUDGE_DSP, and 0x500050 0
 * for a knock-out (the K.O.), 2 for the time running out (JUDGE_DSP_INT's
 * not_scr_bg_move bit 0) or a ring out, which StF never has. _sub_mode
 * stays FIGHT_DSP, so cam_mode_10 keeps following. */
static void round_judge(void) {
    short e0 = (short)RH(robs[0], ROB_ENERGY), e1 = (short)RH(robs[1], ROB_ENERGY);
    u32 l0 = RW(robs[0], ROB_FLAG) & ROB_F_LOST, l1 = RW(robs[1], ROB_FLAG) & ROB_F_LOST;
    if (l0 != l1) (RAM8(l0 ? G_ROUND_WINS1 : G_ROUND_WINS0))++;
    else if (e0 != e1) (RAM8(e0 > e1 ? G_ROUND_WINS0 : G_ROUND_WINS1))++;
    if (ring_out) ring_msg(1u);
    RAM8(G_SUB_MODE + 1u) = SUB_JUDGE_DSP;
    RAM8(G_JUDGE) = (l0 | l1) && !ring_out ? 0u : 2u;
    snd_request_u(SND_GONG);
    over = 180u;
}

/* Three seconds after a round is decided (at once on quit): the next round,
 * or the setup once a fighter has won the match. Returns 0 then: no more
 * fight steps this pass. */
static u32 round_end(void) {
    u32 won = menu_val[M_ROUND];
    if (!quit && --over) return 1u;
    if (ring_out) ring_msg(0u);
    if (quit || RAM8(G_ROUND_WINS0) >= won || RAM8(G_ROUND_WINS1) >= won) {
        menu_open();
        RAM8(G_ROUND_WINS0) = RAM8(G_ROUND_WINS1) = 0u;
        round_start(fs, 0u);
        snd_request_u(SND_RESET);
        over = judging = quit = 0u;
        return 0u;
    }
    round_start(fs, 1u);
    snd_round(stage, cur_stage, 0u);
    over = 0u;
    return 1u;
}

/* One 60 Hz frame of the fight (or of the replay): StF's tasks, then the
 * round's end looked for: an armour break's replay first (FV's FIGHT_DSP),
 * a knock-out (a fighter's w0 bit 5) or the clock's end, found here at the
 * end of the step it comes in. The round is judged four steps on: StF's and
 * VF2's FIGHT_DSP find it the next step, and JUDGE_INT and JUDGE_WAIT pass a
 * step each before JUDGE_DSP_INT. The fighters fight on meanwhile, the clock
 * stopped. Returns 0 when the match is over: no more steps this pass. */
static u32 fight_frame(const u32 pad[2]) {
    if (rep_on) { rep_step(); return 1u; }
    fight_step(pad, !over && !judging);  /* the clock stops once the round's end is found */
    if (in_menu) return 1u;
    if (!over && !quit) ring_out_step(cur_stage);
    if (!over && !quit && !judging && rep_watch()) return 1u;
    if (quit || over) return round_end();
    if (judging) { if (!--judging) round_judge(); return 1u; }
    if (((RW(robs[0], ROB_FLAG) | RW(robs[1], ROB_FLAG)) & ROB_F_LOST) || GAME_TIMER <= 0) judging = 4u;
    return 1u;
}

/* StF steps its fighters once a 60 Hz frame and draws every other one: a
 * frame of the motion for every vblank since the last pass (up to four),
 * the last one's matrices drawn. */
static void fight_frames(const u32 pad[2]) {
    u32 n = frame_counter - step;
    if (n > 4u) n = 4u;
    if (n == 0u) n = 1u;
    step = frame_counter;
    while (n--)
        if (!fight_frame(pad)) break;
}

/* The frame's start: the list, the camera and the light, the sky, the
 * moving texture points and the stage. */
static void scene_begin(void) {
    m2_frame_begin();
    m2_obj_frame_setup();
    clear_buffer_ptr();
    send_materials(cur_stage->mat);
    camera_stf(cur_stage);
    sky_frame(cur_stage);
    sky_storm_frame(cur_stage);
    osage_camera();
    m2_geo_fifo_light(m2_obj_fb(light[0]), m2_obj_fb(light[1]), m2_obj_fb(light[2]));
    move_tpd_send(&cur_stage->tpd);
    polys = 0u;
    draw_stage(cur_stage);
    pn[0] = polys;
}

/* The frame's rest, after the fighters are stepped: the HUD, the eyes, the
 * sway chains, the shadows inside the ring (or Aurora's reflections), then
 * the fighters in one more window, over the stage, the shadows on it and
 * the reflections, as StF draws them (camera_init's set_window(win_down)
 * before rob_disp) and FV over its cage; the afterimages, the projectiles,
 * the effects and the polygon counter. */
static void scene_end(void) {
    u32 i;
    if (!in_menu) hud_draw();
    eyes_frame(&cur_stage->tpd);
    osage_step();
    kage_light(cur_stage);
    kage_inside(cur_stage);
    if (cur_stage->slot == KAGE_NO_INSIDE) mirror_draw(cur_stage, fs, pn);
    else pn[1] = pn[2] = 0u;
    m2_geo_fifo_window_full();
    for (i = 0; i < 2u; i++) { polys = 0u; draw_fighter(&fs[i], i, 0u); spin_frame(i); kage_outside(i); pn[1u + i] += polys; }
    zanzou_draw(pn);
    tobi_draw(pn);
    effects_draw();
    if (in_menu) poly_win_draw(pn);
    *(volatile u32 *)ZCLIP_REG = 0xFFFF00FFu;
    m2_frame_commit();
}

/* 60 fps, as StF and VF2 run: a pass a vsync, the fighters stepped once
 * and drawn every frame. StF's frame_counter counts its 60 Hz loop and
 * sub_2435C runs once a pass, after the wait for the vsync. A pass that
 * runs past a vsync steps the fighters for each vblank it took, so the
 * count follows the vblanks. Linked, a pass is a frame of both boards',
 * however long it waited. */
static void vsync_wait(u32 lp) {
    u32 v = frameVBL;
    /* m2_vsync's wait, sending the sound queue meanwhile */
    while (frameVBL == v) snd_pump();
    v = frameVBL; frame_counter += lp == LP_TICK ? 1u : v - vbl; vbl = v;
    RAM32(G_FRAME_COUNTER) = frame_counter;
    if (cur_stage->slot != 0xFFFFu) stf_call(stf_sub_2435C, robs[0], robs[1], 0u);
}

int main(void) {
    u32 boot = boot_board();
    vbl = frameVBL;
    for (;;) {
        m2_player_t p[2];
        u32 i, e, pad[2] = { 0u, 0u }, pb[2], lp;
        lk_u32 in[2];
        p[0] = m2_player(0); p[1] = m2_player(1);
        /* each pad, start as LINK_START; linked, the cabinet's two pads
         * are its player's, and each player's comes from both boards */
        for (i = 0; i < 2u; i++) pb[i] = pad_bits(&p[i]) | (p[i].start ? LINK_START : 0u);
        /* alone, a fight keeps the other cabinet waiting: the boards link
         * from the setup */
        link.hold = !in_menu;
        if (boot) lp = boot, boot = 0u;
        else {
            link_set(set);
            lp = link_pass(pb[0] | pb[1], set, in, frameVBL, link_wait);
        }
        if (lp == LP_TICK) { pb[0] = in[0]; pb[1] = in[1]; }
        if (lp == LP_SYNC || lp == LP_DROP) { match_reset(lp); continue; }
        e = edges((pb[0] >> 8 & 1u) | (pb[1] >> 8 & 1u) << 1, &held);
        if (in_menu) menu_frame((pb[0] | pb[1]) & 0xFFu, e);
        else {
            pad[0] = pb[0] & 0xFFu; pad[1] = pb[1] & 0xFFu;
            /* both starts at once: back to the setup */
            if ((e & 3u) && (pb[0] & pb[1] & LINK_START)) quit = 1u;
        }

        scene_begin();
        /* alone, the pads again for the fight, read as late as StF's
         * rob_control reads them (after the frame's first tasks), not at
         * the vblank's first instant */
        if (!in_menu && lp != LP_TICK) {
            p[0] = m2_player(0); p[1] = m2_player(1);
            for (i = 0; i < 2u; i++) pad[i] = pad_bits(&p[i]) & 0xFFu;
        }
        fight_frames(pad);
        if (lp == LP_TICK) link_check(link_sum(in_menu, over));
        scene_end();
        vsync_wait(lp);
    }
    return 0;
}

